schema_version.evidence:
"schema_version": {
      "description": "The version number of the schema in major.minor.patch format.",
      "type": "string",
      "pattern": "^[0-9]{1,}.[0-9]{1,}.[0-9]{1,}$",
      "example": "4.6.1"
    }

secondary_project.evidence:
"secondary_project": {
      "type": "array",
      "name": "Secondary project",
      "description": "State the secondary project(s) that this data belongs to e.g. 'AQUA-FAANG', 'GENE-SWitCH' or 'BovReg'. Please use your official consortium shortened acronym if available. If your secondary project is not in the list, please contact the faang-dcc helpdesk to have it added. If your project uses the FAANG data portal project slices (https://data.faang.org/projects) then this field is required to ensure that your data appears in the data slice.",
      "items": {
        "type": "object",
        "required": ["value"],
        "properties": {
          "value": {
            "type": "string",
            "enum": [
              "AQUA-FAANG",
              "GENE-SWitCH",
              "BovReg",
              "Bovine-FAANG",
              "EFFICACE",
              "GEroNIMO",
              "RUMIGEN",
              "Equine-FAANG",
              "Holoruminant",
              "USPIGFAANG"
            ]
          },
          "mandatory": {
            "const": "optional"
          }
        }
      }
    }

sample_storage.evidence:
"sample_storage": {
      "type": "object",
      "name": "sample storage",
      "description": "How the sample was stored. Temperatures are in celsius. 'Frozen, vapor phase' refers to storing samples above liquid nitrogen in the vapor.",
      "required": ["value"],
      "properties": {
        "value": {
          "type": "string",
          "enum": [
            "ambient temperature",
            "cut slide",
            "fresh",
            "frozen, -70 freezer",
            "frozen, -150 freezer",
            "frozen, liquid nitrogen",
            "frozen, vapor phase",
            "paraffin block",
            "RNAlater, frozen",
            "TRIzol, frozen"
          ]
        },
        "mandatory": {
          "const": "optional"
        }
      }
    }

sample_storage_processing.evidence:
"sample_storage_processing": {
      "type": "object",
      "name": "sample storage processing",
      "description": "How the sample was prepared for storage.",
      "required": ["value"],
      "properties": {
        "value": {
          "type": "string",
          "enum": [
            "cryopreservation in liquid nitrogen (dead tissue)",
            "cryopreservation in dry ice (dead tissue)",
            "cryopreservation of live cells in liquid nitrogen",
            "cryopreservation, other",
            "formalin fixed, unbuffered",
            "formalin fixed, buffered",
            "formalin fixed and paraffin embedded",
            "fresh",
            "not applicable",
            "not collected",
            "not provided",
            "restricted access"
          ]
        },
        "mandatory": {
          "const": "recommended"
        }
      }
    }

